/**
 * @file console.c
 * @brief Standard output redirection to USART3.
 */

#include "usart.h"

/**
 * @brief Write standard output data to USART3.
 *
 * Overrides the weak newlib system-call implementation generated by
 * STM32CubeIDE and redirects printf() output to the ST-LINK Virtual COM Port.
 *
 * @param file File descriptor supplied by newlib. Not used.
 * @param ptr Pointer to the output data.
 * @param len Number of bytes to transmit.
 *
 * @return
 *      - len Number of transmitted bytes.
 *      - 0   No data to transmit.
 *      - -1  UART transmission failed.
 */
int _write(int file, char *ptr, int len)
{
    (void)file;

    if ((ptr == NULL) || (len <= 0))
    {
        return 0;
    }

    if (HAL_UART_Transmit(&huart3, (uint8_t *)ptr, (uint16_t)len,
                          HAL_MAX_DELAY) != HAL_OK)
    {
        return -1;
    }

    return len;
}
